import {MarkdownBlock} from '../../../src/components/markdown/markdown';
import React from 'react';import {createRoot} from 'react-dom/client';import {MemoryRouter,Routes,Route,useNavigate,useLocation} from 'react-router-dom';
import {MailRoute} from '../../../src/react-app/domains/mail/mail-route';
import {AppMenuProvider} from '../../../src/react-app/shell/app-menu';
import {MailChatSourceNotice} from '../../../src/react-app/domains/mail/mail-chat-source-notice';
import {getComposerDraft,useComposerStateStore} from '../../../src/react-app/domains/session/surface/composer-state-store';
import {MailAttachmentPreview} from '../../../src/react-app/domains/session/artifacts/mail-attachment-preview';
import {usePanelTabStore,EVALS_PANEL_SESSION_ID} from '../../../src/react-app/domains/session/panel/panel-tab-store';
const bytes=new TextEncoder().encode('Synthetic contract appendix. Original local bytes.');
const sha=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),value=>value.toString(16).padStart(2,'0')).join('');
const body=new TextEncoder().encode(JSON.stringify({version:1,bodies:[{partId:'plain',contentType:'text/plain',text:'Please review the attached contract in the selected matter workspace.'}]}));
const bodySha=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',body)),value=>value.toString(16).padStart(2,'0')).join('');
const item={accountId:'a',key:'m1',locator:{provider:'gmail',messageId:'m1'},subject:'Synthetic contract review',threadId:'thread',rfcMessageId:null,removed:false,memberships:['INBOX'],contentState:'complete',metadata:{subject:'Synthetic contract review',from:'Alex <alex@example.test>',to:'Lawyer <lawyer@example.test>',cc:null,bcc:null,replyTo:null,date:null,messageId:null},receivedAt:1789200000000,rawReferenceId:null,isRead:true};
const part={key:'attachment',kind:'attachment',partId:'attachment',state:'stored',referenceId:'sha256:'+sha,bytes:bytes.length,sha256:sha,bytesAvailable:true,filename:'contract.txt',contentType:'text/plain',contentId:null};
window.calls=[];window.copies=[];window.removed=false;window.cancelCopy=false;
localStorage.setItem('legalwork.server.urlOverride','http://127.0.0.1:4321');localStorage.setItem('legalwork.server.token','synthetic');localStorage.setItem('legalwork.server.hostToken','synthetic');
window.fetch=async(input,options)=>{const path=new URL(String(input)).pathname,request=options?.body?JSON.parse(options.body):null;window.calls.push({path,request,origin:new URL(String(input)).origin});let value;if(path.endsWith('/status'))value={state:'ready'};else if(path.endsWith('/accounts'))value={items:[{id:'a',provider:'gmail',displayName:'Personal firm mail'}],nextCursor:null};else if(path.endsWith('/actions/query'))value={items:[],nextCursor:null};else if(path.endsWith('/sync'))value={state:'complete',enumerated:1,downloaded:1,projected:1,failed:0,pending:0,error:null};else if(path.endsWith('/query'))value={items:[item],nextCursor:null};else if(path.endsWith('/read')){if(window.removed)return new Response(null,{status:404});value=item;}else if(path.endsWith('/parts'))value={items:[{...part,key:'body',kind:'body',partId:'',referenceId:'sha256:'+bodySha,bytes:body.length,sha256:bodySha,filename:null,contentType:'application/json'},part],nextCursor:null};else if(path.endsWith('/content')){const data=request.request.partId==='attachment'?bytes:body,hash=request.request.partId==='attachment'?sha:bodySha;value={accountId:'a',referenceId:'sha256:'+hash,offset:0,totalBytes:data.length,sha256:hash,data:btoa(String.fromCharCode(...data)),nextOffset:null};}else value={items:[],nextCursor:null};return Response.json(value);};
function Preview(){const tab=usePanelTabStore(s=>s.sessions[EVALS_PANEL_SESSION_ID]?.tabs.find(t=>t.type==='artifact'&&t.mailSourceId));return tab?.mailSourceId?<aside aria-label="Internal attachment viewer"><MailAttachmentPreview sourceId={tab.mailSourceId}/></aside>:null;}
function Chat(){const location=useLocation(),id=location.state?.sessionId||'existing';const draft=useComposerStateStore(s=>getComposerDraft(s,id));return <section aria-label="Chosen workspace chat"><h2>Acme matter · Existing review chat</h2><MailChatSourceNotice sessionId={id}/><MarkdownBlock text={draft.match(/\[Source email\]\([^\n]+\)/)?.[0]||''}/><textarea aria-label="Prepared chat draft" readOnly value={draft}/><p>Draft only. No model request has been made.</p></section>;}
function App(){const navigate=useNavigate();const [pulse,setPulse]=React.useState(0);window.rerenderParent=()=>setPulse(value=>value+1);const bridge=React.useMemo(()=>({workspaces:[{id:'local',name:'Acme matter',remote:false},{id:'remote',name:'Remote matter',remote:true}],sessions:async()=>[{id:'existing',title:'Existing review chat'}],prepare:async(workspaceId,sessionId)=>{window.calls.push({prepare:workspaceId,sessionId});return{workspaceId:'server-'+workspaceId,sessionId:sessionId||'new-chat',client:{writeWorkspaceBinaryFile:async(id,input)=>{window.copies.push({id,path:input.path,text:new TextDecoder().decode(input.data)});if(window.cancelCopy)await new Promise(resolve=>{window.releaseCopy=resolve;});return{ok:true,path:input.path,updatedAt:1};}},assertCurrent:async()=>{},open:()=>navigate('/chat',{state:{sessionId:sessionId||'new-chat'}})};}}),[navigate]);return <AppMenuProvider><Routes><Route path="/mail" element={<><MailRoute chatBridge={bridge}/><Preview/></>}/><Route path="/chat" element={<Chat/>}/></Routes></AppMenuProvider>;}
useComposerStateStore.getState().setDraft('existing','Existing instructions stay here.');
createRoot(document.getElementById('root')).render(<MemoryRouter initialEntries={['/mail']}><App/></MemoryRouter>);
